# `deployment.environment.name` has no constant on the legacy ResourceAttributes class in
# opentelemetry-semantic-conventions 0.66b0 — only the deprecated `DEPLOYMENT_ENVIRONMENT` —
# so the key is written as a literal. Checked against the installed package; re-check rather
# than assume if you bump the dependency.
_DEPLOYMENT_ENVIRONMENT_NAME = "deployment.environment.name"

# --- Exporter selection --------------------------------------------------------------
# OTEL_TRACES_EXPORTER / OTEL_METRICS_EXPORTER / OTEL_LOGS_EXPORTER select `otlp`, `console` or
# `none`. Building the providers by hand (rather than via `opentelemetry-instrument`) means
# honouring them here. The default is `none` when no endpoint is configured: defaulting to otlp
# would point at localhost:4317, dropping every span while a reconnect loop burns CPU. `console`
# prints to stdout with no collector running.
_endpoint = os.getenv("OTEL_EXPORTER_OTLP_ENDPOINT", "")
_default_exporter = "otlp" if _endpoint else "none"

# This plugin standardizes on OTLP/gRPC (4317); the SDK default is http/protobuf (4318).
os.environ.setdefault("OTEL_EXPORTER_OTLP_PROTOCOL", "grpc")


def _choice(var: str) -> str:
    return (os.getenv(var) or _default_exporter).strip().lower()


# Warn only when nothing is actually being exported — evaluated after the defaults are
# applied, so an explicit OTEL_TRACES_EXPORTER=console is not told it emits nothing.
if all(
    _choice(v) == "none"
    for v in ("OTEL_TRACES_EXPORTER", "OTEL_METRICS_EXPORTER", "OTEL_LOGS_EXPORTER")
):
    print(
        "[otel] No OTEL_EXPORTER_OTLP_ENDPOINT is configured and no exporter was selected, so "
        "this process emits no telemetry. Set OTEL_EXPORTER_OTLP_ENDPOINT for your collector, "
        "or OTEL_TRACES_EXPORTER=console to print spans locally."
    )

resource = Resource.create({
    ResourceAttributes.SERVICE_NAME: os.getenv("OTEL_SERVICE_NAME", "inventory-api"),
    ResourceAttributes.SERVICE_VERSION: os.getenv("OTEL_SERVICE_VERSION", "0.3.1"),
    # Emit service.namespace only when the context JSON has a confirmed namespace; omit otherwise.
    ResourceAttributes.SERVICE_NAMESPACE: os.getenv("OTEL_SERVICE_NAMESPACE", "storefront"),
    _DEPLOYMENT_ENVIRONMENT_NAME: os.getenv("DEPLOYMENT_ENV", "development"),
})

# Traces. On `none` no provider is registered at all, leaving the API's default no-op in
# place: spans are then never built, rather than built and dropped at export. Application
# code calling tracer.start_as_current_span() keeps working either way.
_traces = _choice("OTEL_TRACES_EXPORTER")
_tracer_provider = None
if _traces in ("otlp", "console"):
    _tracer_provider = TracerProvider(resource=resource, shutdown_on_exit=False)
    if _traces == "otlp":
        _tracer_provider.add_span_processor(
            BatchSpanProcessor(OTLPSpanExporter(endpoint=_endpoint or None))
        )
    else:
        # Simple, not Batch: console output is for a human watching stdout, so it should
        # appear as spans end rather than on the batch interval.
        _tracer_provider.add_span_processor(SimpleSpanProcessor(ConsoleSpanExporter()))
    trace.set_tracer_provider(_tracer_provider)

# Metrics
_metrics = _choice("OTEL_METRICS_EXPORTER")
_meter_provider = None
if _metrics in ("otlp", "console"):
    _exporter = (
        OTLPMetricExporter(endpoint=_endpoint or None)
        if _metrics == "otlp"
        else ConsoleMetricExporter()
    )
    _meter_provider = MeterProvider(
        resource=resource,
        shutdown_on_exit=False,  # shutdown() below owns the exit-time flush
        metric_readers=[
            PeriodicExportingMetricReader(_exporter, export_interval_millis=30_000)
        ],
    )
    metrics.set_meter_provider(_meter_provider)

    # Runtime metrics: this process's CPU, memory, threads, open files and garbage collection,
    # with no application code. Host-wide metrics (system.*) are left out on purpose: every
    # replica on a machine would report the same numbers, and the Collector's hostmetrics
    # receiver is the place for them. The package is optional by design (it needs psutil, which
    # has a compiled part): without it the service starts as before and says so once.
    # Beta package: some of these metric names are not yet stable in the semantic conventions
    # and may be renamed by a later release.
    try:
        from opentelemetry.instrumentation.system_metrics import SystemMetricsInstrumentor

        SystemMetricsInstrumentor(config={
            "process.cpu.time": ["user", "system"],
            "process.cpu.utilization": ["user", "system"],
            "process.memory.usage": None,
            "process.memory.virtual": None,
            "process.thread.count": None,
            "process.open_file_descriptor.count": None,
            "cpython.gc.collections": None,
            "cpython.gc.collected_objects": None,
            "cpython.gc.uncollectable_objects": None,
        }).instrument(meter_provider=_meter_provider)
    except ImportError:
        print(
            "[otel] opentelemetry-instrumentation-system-metrics is not installed, so this "
            "process emits no runtime metrics (CPU, memory, garbage collection)."
        )

# Logs — EXPERIMENTAL (requires --experimental). Console uses Simple export so records print as
# they arrive; otlp batches. The stdlib root logger is bridged to OTel so existing `logging`
# calls export as OTLP log records.
_logs = _choice("OTEL_LOGS_EXPORTER")
_logger_provider = None
if _logs in ("otlp", "console"):
    _logger_provider = LoggerProvider(resource=resource, shutdown_on_exit=False)
    if _logs == "otlp":
        _logger_provider.add_log_record_processor(
            BatchLogRecordProcessor(OTLPLogExporter(endpoint=_endpoint or None))
        )
    else:
        _logger_provider.add_log_record_processor(
            SimpleLogRecordProcessor(ConsoleLogExporter())
        )
    set_logger_provider(_logger_provider)
    logging.getLogger().addHandler(LoggingHandler(logger_provider=_logger_provider))


# --- Trace IDs in log lines ------------------------------------------------------------
# A log line written during a request says which trace it belongs to, so the line you are
# reading leads to the trace (and back). This works on the standard `logging` module and
# keeps your logger, handlers and format string as they are:
#   - every record gets `otelTraceID` and `otelSpanID` fields ("0" outside a span), the names
#     opentelemetry-instrumentation-logging uses, so a JSON formatter that writes extra
#     fields includes them and a format string can reference %(otelTraceID)s;
#   - a line rendered by the plain `logging.Formatter` gets ` trace_id=... span_id=...`
#     appended. A custom formatter class and a line that is already JSON are left alone,
#     and so is a line that already shows the trace ID.
# OTEL_AS_CODE_LOG_TRACE_IDS=off stops the appending; the fields stay. print() and loggers
# that bypass `logging` are not covered.
def _add_trace_ids_to_logs():
    import logging

    previous_factory = logging.getLogRecordFactory()

    def record_factory(*args, **kwargs):
        record = previous_factory(*args, **kwargs)
        context = trace.get_current_span().get_span_context()
        valid = context.is_valid
        record.otelTraceID = format(context.trace_id, "032x") if valid else "0"
        record.otelSpanID = format(context.span_id, "016x") if valid else "0"
        return record

    logging.setLogRecordFactory(record_factory)

    if os.getenv("OTEL_AS_CODE_LOG_TRACE_IDS", "").strip().lower() in ("0", "false", "off"):
        return
    format_message = logging.Formatter.formatMessage

    def format_message_with_ids(self, record):
        line = format_message(self, record)
        trace_id = getattr(record, "otelTraceID", "0")
        if (
            type(self) is logging.Formatter
            and trace_id != "0"
            and trace_id not in line
            and not line.lstrip().startswith(("{", "["))
        ):
            line = f"{line} trace_id={trace_id} span_id={record.otelSpanID}"
        return line

    logging.Formatter.formatMessage = format_message_with_ids


_add_trace_ids_to_logs()


def _fastapi_traces_itself():
    # FastAPI 0.142.0 and later reports its own request spans and metrics once a provider is
    # registered (above), under the stable HTTP names: http.server.request.duration in seconds,
    # http.response.status_code. The instrumentation package would switch that off and report
    # the old names (http.server.duration, http.status_code) unless
    # OTEL_SEMCONV_STABILITY_OPT_IN is set, so it is only used where FastAPI has no telemetry
    # of its own. Checked by what is installed, not by the version your requirements allow.
    # OTEL_AS_CODE_FASTAPI_SOURCE=package keeps the package, for a service whose existing
    # dashboards still query the old names.
    if os.getenv("OTEL_AS_CODE_FASTAPI_SOURCE", "").strip().lower() == "package":
        return False
    try:
        import fastapi.telemetry  # noqa: F401
    except ImportError:
        return False
    return True


def instrument_fastapi(app):
    """Call this after creating your FastAPI app instance."""
    if not _fastapi_traces_itself():
        from opentelemetry.instrumentation.fastapi import FastAPIInstrumentor
        FastAPIInstrumentor.instrument_app(app)
    _flush_on_app_shutdown(app)
    return app


# --- Flushing on the way out -----------------------------------------------------------
# Spans, metrics and logs are sent in batches, so whatever is still buffered when the
# process stops has to be flushed, or the last few seconds of telemetry are lost on every
# deploy. No single hook covers every server, so the bootstrap uses three:
#   1. atexit: a normal interpreter exit (gunicorn's workers, hypercorn, daphne).
#   2. SIGTERM: Python runs no exit handlers when it dies from a signal, which is how
#      waitress, `flask run` and `runserver` stop, and uvicorn re-raises SIGTERM after
#      its graceful shutdown for the same result.
#   3. The app's shutdown event (FastAPI): runs after in-flight requests finish, so it
#      also catches their spans under `uvicorn --workers`.
# Each waits at most _FLUSH_TIMEOUT_S, so a collector that is down cannot hold up a stop.
_FLUSH_TIMEOUT_S = 5
_shutdown_done = False


def _providers():
    return [p for p in (_tracer_provider, _meter_provider, _logger_provider) if p is not None]


def _bounded(work):
    # In its own thread, so a flush never deadlocks on a lock the interrupted main thread
    # holds, and never waits longer than the timeout.
    worker = threading.Thread(target=work, name="otel-flush", daemon=True)
    worker.start()
    worker.join(_FLUSH_TIMEOUT_S)


def flush():
    """Send what is buffered and keep running. Safe to call any number of times."""
    if _shutdown_done:
        return

    def work():
        for provider in _providers():
            try:
                provider.force_flush(timeout_millis=_FLUSH_TIMEOUT_S * 1000)
            except Exception:  # a failed flush must never break the app's shutdown
                pass

    _bounded(work)


def shutdown():
    """Flush and stop the providers. Only the first call does anything."""
    global _shutdown_done
    if _shutdown_done:
        return
    _shutdown_done = True

    def work():
        for provider in _providers():
            try:
                provider.shutdown()
            except Exception:
                pass

    _bounded(work)


def _flush_on_app_shutdown(app):
    """Flush when the app's lifespan ends, whether it uses `lifespan=` or shutdown events."""
    original = getattr(app.router, "lifespan_context", None)
    if original is None:
        return

    @contextlib.asynccontextmanager
    async def lifespan(running_app):
        async with original(running_app) as state:
            yield state
        flush()

    app.router.lifespan_context = lifespan


def _on_sigterm(signum, frame):
    if callable(_previous_sigterm):
        # A server's own handler is in charge and will stop gracefully. Flush in the
        # background and hand over at once, so its event loop and its in-flight requests
        # never wait on a collector; atexit or the app's shutdown event does the final flush.
        threading.Thread(target=flush, name="otel-flush-signal", daemon=True).start()
        _previous_sigterm(signum, frame)
        return
    flush()
    if _previous_sigterm == signal.SIG_DFL:
        # Nobody else handles SIGTERM: end the way the process would have ended without us.
        signal.signal(signal.SIGTERM, signal.SIG_DFL)
        os.kill(os.getpid(), signum)
    # SIG_IGN: the process chose to ignore SIGTERM, so keep ignoring it.


_previous_sigterm = None
if _providers():
    atexit.register(shutdown)
    try:
        if signal.getsignal(signal.SIGTERM) is not None:  # None: set outside Python, can't chain
            _previous_sigterm = signal.signal(signal.SIGTERM, _on_sigterm)
    except ValueError:
        pass  # not the main thread: signal handlers can't be set here; atexit still applies
